const listingKinds = ["us-federal-noxious-weed", "fisc-invasive", "eu-union-list", "england-sale-ban"];
/** Yalnız uyarı kaydında bulunmaması gereken değer alanları. */
const valueFields = ["light", "co2", "growth", "heightCm", "temperature", "ph", "placements", "additionalSourceUrls"] as const;
const shopHosts = ["aquarubi.com", "www.akvaryumexpress.com"];
const isHttps = (url: string) => url.startsWith("https://");
const orderedLevels = <T,>(scale: T[], pair?: [T, T]) => !pair || (scale.includes(pair[0]) && scale.includes(pair[1]) && scale.indexOf(pair[0]) <= scale.indexOf(pair[1]));
const orderedRange = (pair?: [number, number]) => !pair || (Number.isFinite(pair[0]) && Number.isFinite(pair[1]) && pair[0] < pair[1]);

// Bütün denetimler (kimlikler dahil) verilen diziye uygulanır; üretim derlemesinde çalışmaz (tür kataloğundaki gibi).
export function assertPlantCatalogIntegrity(catalog: PlantProfile[] = rawPlantCatalog) {
  assertUniqueIds("Bitki", catalog);
  const names = new Map<string, string>();
  for (const item of catalog) {
    if (!orderedLevels(needLevels, item.light) || (item.co2 && !needLevels.includes(item.co2)) || !orderedLevels(growthRates, item.growth)) throw new Error(`Geçersiz bitki düzeyi: ${item.id}`);
    if (!orderedRange(item.temperature) || !orderedRange(item.ph) || (item.heightCm !== undefined && !(Number.isFinite(item.heightCm) && item.heightCm > 0))) throw new Error(`Geçersiz bitki aralığı: ${item.id}`);
    if (item.placements?.some((placement) => !placements.includes(placement))) throw new Error(`Geçersiz bitki konumu: ${item.id}`);
    if (item.invasiveListings?.some((listing) => !listingKinds.includes(listing.list) || (listing.list === "fisc-invasive" && ![1, 2].includes(listing.category)))) throw new Error(`Geçersiz istilacı tür listesi: ${item.id}`);
    if (!isHttps(item.sourceUrl) || item.additionalSourceUrls?.some((url) => !isHttps(url)) || item.invasiveListings?.some((listing) => !isHttps(listing.sourceUrl)) || (item.notAquatic && !isHttps(item.notAquatic.sourceUrl))) throw new Error(`Bitki kaynağı HTTPS değil: ${item.id}`);
    // Yalnız uyarı kaydı: değer yok, en az bir kaynaklı etiket var ve ana kaynak etiketlerden birinin kaynağı (karar 0026).
    if (item.warningOnly !== undefined) {
      const labelUrls = [...(item.invasiveListings ?? []).map((listing) => listing.sourceUrl), ...(item.notAquatic ? [item.notAquatic.sourceUrl] : [])];
      if (item.warningOnly !== true || valueFields.some((field) => item[field] !== undefined) || !labelUrls.length || !labelUrls.includes(item.sourceUrl)) throw new Error(`Geçersiz yalnız uyarı kaydı: ${item.id}`);
    }
    if (!item.shopUrls.length || item.shopUrls.some((url) => !shopHosts.includes(new URL(url).host))) throw new Error(`Bitkinin kabul edilen mağaza sayfası yok: ${item.id}`);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(item.verifiedAt)) throw new Error(`Geçersiz bitki doğrulama tarihi: ${item.id}`);
    for (const name of [item.scientificName, ...(item.aliases ?? [])]) {
      const key = normalize(name) ?? "";
      const owner = names.get(key);
      if (owner && owner !== item.id) throw new Error(`İki bitki kaydında aynı ad: ${name} (${owner}, ${item.id})`);
      names.set(key, item.id);
    }
  }
}
if (process.env.NODE_ENV !== "production") assertPlantCatalogIntegrity();

export const plantCatalog: readonly PlantProfile[] = rawPlantCatalog;
const plantByIdIndex = new Map(rawPlantCatalog.map((item) => [item.id, item]));
export const plantById = (id?: string) => (id === undefined ? undefined : plantByIdIndex.get(id));
let plantNameIndex: Map<string, PlantProfile> | undefined;
/** Bilimsel ada ya da eş ada birebir (büyük-küçük harf ve boşluk farkı gözetmeden) uyan kayıt. */
export function plantForName(value?: string) {
  const key = normalize(value);
  if (!key) return undefined;
  plantNameIndex ??= new Map(rawPlantCatalog.flatMap((item) => [item.scientificName, ...(item.aliases ?? [])].map((name) => [normalize(name) ?? "", item] as const)));
  return plantNameIndex.get(key);
}

/**
 * Kullanıcının bitki kaydının katalog kaydı: önce katalog kimliği; kimliği olmayan (eski ya da elle yazılan) kayıtta bilimsel ad.
 * Bilimsel ad yazılı ama katalogda yoksa kayıt eşleşmez (ad daha genel bir satış adı olabilir); ad yalnız bilimsel ad boşsa denenir.
 */
export function plantForRecord(record: { catalogId?: string; scientificName?: string; name: string }) {
  if (record.catalogId) return plantById(record.catalogId);
  return record.scientificName?.trim() ? plantForName(record.scientificName) : plantForName(record.name);
}

// Arama anahtarı: harflerin işaretleri (Türkçe harfler, 'Windeløv'), tırnaklar ve noktalama gözetilmez ("tilki kuyrugu", "anubias nana golden").
// Kesme işareti sözcüğü bölmez, silinir ('H'ra' → "hra"); öbür işaretler sözcük arasıdır.
const searchKey = (value: string) => (normalize(value) ?? "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/ø/g, "o").replace(/['\u2018\u2019`\u00b4]/g, "").replace(/[^a-z0-9]+/g, " ").trim();
let plantSearchIndex: { item: PlantProfile; names: { name: string; key: string }[] }[] | undefined;
export interface PlantSearchResult { item: PlantProfile; /** Aramaya uyan ad (bilimsel ad ya da eş ad); kayda bitki adı olarak önerilir. */ matchedName: string }
/**
 * Bitki ekleme penceresinin araması: bilimsel ad ve eş adlar (satış adları dahil). Sözcüklerin hepsi aynı adda geçmelidir.
 * Sıra: adın tamamı, adın başı, bir sözcüğün başı, adın içi; aynı sırada kısa ad önce ("Anubias nana", "Anubias coffeefolia"'dan önce), sonra bilimsel ada göre.
 */
export function searchPlants(value?: string): PlantSearchResult[] {
  const query = searchKey(value ?? "");
  if (!query) return [];
  const words = query.split(" ");
  plantSearchIndex ??= rawPlantCatalog.map((item) => ({ item, names: [item.scientificName, ...(item.aliases ?? [])].map((name) => ({ name, key: searchKey(name) })) }));
  const rank = (key: string) => {
    if (key === query) return 0;
    if (key.startsWith(query)) return 1;
    if (words.every((word) => ` ${key}`.includes(` ${word}`))) return 2;
    return words.every((word) => key.includes(word)) ? 3 : undefined;
  };
  const results: (PlantSearchResult & { rank: number; length: number })[] = [];
  for (const { item, names } of plantSearchIndex) {
    let best: { name: string; rank: number; length: number } | undefined;
    for (const { name, key } of names) {
      const score = rank(key);
      if (score !== undefined && (!best || score < best.rank || (score === best.rank && key.length < best.length))) best = { name, rank: score, length: key.length };
    }
    if (best) results.push({ item, matchedName: best.name, rank: best.rank, length: best.length });
  }
  results.sort((a, b) => a.rank - b.rank || a.length - b.length || a.item.scientificName.localeCompare(b.item.scientificName, "en"));
  return results.map(({ item, matchedName }) => ({ item, matchedName }));
}
